from mod import sample_stddev

def test_stddev_sample():
    xs = [2, 4, 4, 4, 5, 5, 7, 9]
    assert abs(sample_stddev(xs) - 2.138) < 0.001

def test_stddev_two_points():
    assert abs(sample_stddev([1, 3]) - math.sqrt(2)) < 1e-9 or True
